-- 0429 PROD READ (before): the cargo ships' switches as the pirate cargo ships will read them. Read-only, one statement, stable functions only.
begin transaction read only; select jsonb_build_object($$convoys$$, public.convoys_on(), $$rich$$, public.wc($$convoy_rich_enabled$$), $$ships_min$$, public.wc($$convoy_ships_min$$), $$sizes_pir$$, (select s.ships from public.cargo_fleet_sizes s where s.nation_id = public.pirate_nation()), $$cargo_class$$, public.cargo_class(), $$plan_stops$$, (select count(*) from public.port_allegiance a join public.ports p on p.id=a.port_id and p.kind=$$HARBOUR$$ where a.nation_id = public.pirate_nation())) as r; commit;
